        print(" * ")
        expr_print(AR_RIGHT[idx])
        print(")")
        return
    }
    if tag == 5 {
        print("(")
        expr_print(AR_LEFT[idx])
        print(" / ")
        expr_print(AR_RIGHT[idx])
        print(")")
        return
    }
    if tag == 6 {
        print("(0-")
